#include <cstdio>
#include <vector>
#include <string>
#include <algorithm>
#include <iostream>

int main() {
    std::string a, b;
    std::getline(std::cin, a);
    std::getline(std::cin, b);

    int n = (int)a.size(), m = (int)b.size();
    std::vector<int> prev(m + 1, 0), cur(m + 1, 0);

    for (int i = 1; i <= n; ++i) {
        cur.assign(m + 1, 0);
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1])
                cur[j] = prev[j - 1] + 1;
            else
                cur[j] = std::max(prev[j], cur[j - 1]);
        }
        prev = cur;
    }
    printf("%d\n", prev[m]);
    return 0;
}
